// Tests for island/widgets/index.js (generated by tools/catalog.py) and the Iwidgets' meta.js.
// Run: node island/widgets/tests/index.test.js
// The index is the one line a new widget folder adds: this checks it still matches the folders, on
// `main` too, where tools/ doesn't ship.
const fs = require("fs");
const path = require("path");
const assert = require("assert");

const DIR = path.join(__dirname, "..");

function meta(id) {
    const src = fs.readFileSync(path.join(DIR, id, "meta.js"), "utf8").replace(/^\.pragma library.*$/m, "");
    return new Function(src + "\nreturn meta;")();
}

const folders = fs.readdirSync(DIR)
    .filter(n => fs.existsSync(path.join(DIR, n, "meta.js")))
    .sort();
const index = fs.readFileSync(path.join(DIR, "index.js"), "utf8");
const imported = [...index.matchAll(/^\.import "([^/]+)\/meta\.js" as (\w+)$/gm)];
const listed = [...index.matchAll(/^ {4}(\w+): (\w+)\.meta,?$/gm)];

let passed = 0, failed = 0;
function test(name, fn) {
    try {
        fn();
        passed++;
    } catch (e) {
        failed++;
        console.log("FAIL " + name + "\n  " + e.message);
    }
}

test("the index imports exactly the folders that have a meta.js", () => {
    assert.deepStrictEqual(imported.map(m => m[1]), folders);
});

test("every import is listed in WIDGETS, under its folder's name", () => {
    assert.deepStrictEqual(listed.map(m => m[1]), folders);
    assert.deepStrictEqual(listed.map(m => m[2]), imported.map(m => m[2]));
});

test("every meta.js describes its widget", () => {
    for (const id of folders) {
        const m = meta(id);
        assert.ok(m.title, id + ": no title");
        assert.ok(m.icon, id + ": no icon");
        assert.ok(Array.isArray(m.styles) && m.styles.length, id + ": no styles");
        for (const s of m.styles)
            assert.ok(s.id && s.title, id + ": a style needs an id and a title");
        for (const c of m.cards || [])
            assert.ok(m.styles.some(s => s.id === c), id + ": cards names a style it doesn't have: " + c);
        for (const mode of ["compact", "expanded"]) {
            const d = m.defaults[mode];
            assert.ok(d === "hidden" || m.styles.some(s => s.id === d),
                id + ": the " + mode + " default is not one of its styles: " + d);
        }
    }
});

test("every widget folder has a Widget.qml", () => {
    for (const id of folders)
        assert.ok(fs.existsSync(path.join(DIR, id, "Widget.qml")), id + ": no Widget.qml");
});

console.log(passed + " passed, " + failed + " failed");
process.exit(failed ? 1 : 0);
